#!/usr/bin/env node
// devteam: the one script. Node 18+, built-ins only.
//   node docs/devteam/scripts/devteam.mjs <command> [args]      (`help` lists the commands)
//
// Everything structured about a project is a line in the log (schema/log.schema.json), folded by
// time. Everything prose is markdown. This file validates and folds the log, computes the graph,
// status, metrics, roadmap and dashboard from it, runs the checks the supervisor merges on, makes
// worker sessions, serves the dashboard, and gives every role its commands.
//
// Sections: 1 helpers · 2 settings · 3 schema and log · 4 git facts · 5 graph · 6 reviews and the
// definition of done · 7 trust · 8 decide and act · 9 goals, roadmap, retros · 10 metrics and the
// dashboard · 11 sessions (workers, messages, phases, gates) · 12 init, help, dispatch.

import { execFile, execFileSync, spawn, spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
import os from 'node:os';
import fs from 'node:fs';
import http from 'node:http';
import net from 'node:net';
import path from 'node:path';
import { pipeline } from 'node:stream';
import { fileURLToPath } from 'node:url';

// ===== 1. helpers =====

// Projects pin their own Node (asdf, nvm), and the dashboard reruns this file with that Node, so
// say plainly when it is too old instead of failing mid-command. Use nothing newer than Node 18.
if (Number(process.versions.node.split('.')[0]) < 18) {
  process.stderr.write(`devteam: needs Node 18 or newer; this is ${process.version} (check the project's .tool-versions, .nvmrc or .node-version)\n`);
  process.exit(1);
}

// bash-ok: a Claude Code PreToolUse hook on Bash in every Claude Code session the kit starts
// (claudePolicy, supervisorPolicy). An inline rm or rmdir whose path is built from a variable, a
// glob, a brace or $(…) is refused, with worker.md's "Scripts go in files" as the reason, before
// Claude Code stops on its permission prompt ("Dangerous rm operation") in a window nobody
// watches; a subagent's prompt stops its whole session behind it. The session reads the reason and
// writes the script file instead. It runs here, before anything else: it needs no repo, settings or
// log, and the hook runs on every command. It only ever refuses; anything it can't read goes through.
//
// It reads the line as a shell would, enough to find command words: quotes, comments, heredoc
// bodies and redirections are not commands, so `rm` in a grep pattern, a commit message or a PR
// body passes; a $(…) or `…` is read as its own command too. Separators: ; & | newlines ( ).
// Wrappers it looks through: sudo, doas, env, timeout, nice, ionice, nohup, setsid, taskset,
// flock, prlimit, stdbuf, command, builtin, exec, time and the shell's own then/do/else/!.
// sh -c / bash -c and eval are read again. Not covered: xargs rm (its paths come on stdin) and
// find -delete or -exec rm (no variable path in the line).
if (process.argv[2] === 'bash-ok') {
  const WHY = 'Run any multi-step shell command, heredoc, or `rm` of a variable, glob or `$(…)` as a script file you write with your file tool and then run, never inline: a permission prompt stops the whole session. In that file, delete only paths built with `${VAR:?}` on every part, under a directory the script made or names literally, and never a path read from a file or from `$(…)`.';
  // the line as simple commands, each a list of words { text, expands }; subs: the text of each $(…) and `…`
  const lex = (src) => {
    const s = String(src ?? '');
    const cmds = [];
    const subs = [];
    let words = [];
    let w = null;
    let redirect = false;
    const heredocs = [];
    const endWord = () => { if (w) { if (redirect) redirect = false; else words.push(w); } w = null; };
    const endCmd = () => { endWord(); if (words.length) cmds.push(words); words = []; };
    const cur = () => (w ??= { text: '', expands: false });
    // the end of a heredoc body that starts on the line after i: the index after its delimiter line
    const skipBody = (i, delim, tabs) => {
      let j = i;
      for (;;) {
        if (j >= s.length) return s.length;
        const nl = s.indexOf('\n', j);
        const line = s.slice(j, nl < 0 ? s.length : nl);
        j = nl < 0 ? s.length : nl + 1;
        if ((tabs ? line.replace(/^\t+/, '') : line) === delim) return j;
      }
    };
    const heredocAt = (j) => {
      let k = j + 2;
      const tabs = s[k] === '-';
      if (tabs) k++;
      while (s[k] === ' ' || s[k] === '\t') k++;
      let d = '';
      while (k < s.length && !/[\s;&|<>()]/.test(s[k])) { if (!`'"\\`.includes(s[k])) d += s[k]; k++; }
      return { end: k, delim: d, tabs };
    };
    // $( … ) or ` … `: its end, with nesting, quotes and heredoc bodies inside it; its text is read as commands too
    const skipSubst = (i, close) => {
      let depth = 1;
      const pending = [];
      for (let j = i; j < s.length; j++) {
        const c = s[j];
        if (c === '\\') { j++; continue; }
        if (c === '\n' && pending.length) { let k = j + 1; while (pending.length) { const h = pending.shift(); k = skipBody(k, h.delim, h.tabs); } j = k - 1; continue; }
        if (close === ')' && c === '<' && s[j + 1] === '<' && s[j + 2] !== '<') { const h = heredocAt(j); if (h.delim) pending.push(h); j = h.end - 1; continue; }
        if (close === ')' && c === "'") { const k = s.indexOf("'", j + 1); if (k < 0) return s.length; j = k; continue; }
        if (close === ')' && c === '"') { let k = j + 1; while (k < s.length && s[k] !== '"') k += s[k] === '\\' ? 2 : 1; j = k; continue; }
        if (close === ')' && c === '(') depth++;
        if (c === close && --depth === 0) { subs.push(s.slice(i, j)); return j + 1; }
      }
      return s.length;
    };
    let i = 0;
    while (i < s.length) {
      const c = s[i];
      if (c === '\n') {
        endCmd();
        i++;
        while (heredocs.length) { const h = heredocs.shift(); i = skipBody(i, h.delim, h.tabs); }
        continue;
      }
      if (c === ' ' || c === '\t') { endWord(); i++; continue; }
      if (c === '\\') { if (s[i + 1] === '\n') { i += 2; continue; } cur().text += s[i + 1] ?? ''; i += 2; continue; }
      if (c === '#' && !w) { const nl = s.indexOf('\n', i); i = nl < 0 ? s.length : nl; continue; }
      if (c === ';' || c === '&' || c === '|' || c === '(' || c === ')') {
        if (c === '&' && (s[i - 1] === '>' || s[i + 1] === '>')) { i++; continue; }
        endCmd(); i++; continue;
      }
      if (c === '<' && s[i + 1] === '<' && s[i + 2] !== '<') { endWord(); const h = heredocAt(i); if (h.delim) heredocs.push(h); i = h.end; continue; }
      if (c === '<' || c === '>') {
        if (w && /^\d+$/.test(w.text) && !w.expands) w = null;
        endWord();
        let j = i;
        while (s[j] === '<' || s[j] === '>' || s[j] === '&' || s[j] === '|') j++;
        if (/^[0-9-]/.test(s[j] ?? '') && s[j - 1] === '&') { while (/[0-9-]/.test(s[j] ?? '')) j++; i = j; continue; }
        redirect = true;
        i = j;
        continue;
      }
      if (c === "'") { const k = s.indexOf("'", i + 1); cur().text += s.slice(i + 1, k < 0 ? s.length : k); i = k < 0 ? s.length : k + 1; continue; }
      if (c === '"') {
        let j = i + 1;
        while (j < s.length && s[j] !== '"') {
          if (s[j] === '\\') { cur().text += s[j + 1] ?? ''; j += 2; continue; }
          if (s[j] === '$' || s[j] === '`') {
            cur().expands = true;
            if (s[j] === '$' && s[j + 1] === '(') { const e = skipSubst(j + 2, ')'); cur().text += s.slice(j, e); j = e; continue; }
            if (s[j] === '`') { const e = skipSubst(j + 1, '`'); cur().text += s.slice(j, e); j = e; continue; }
          }
          cur().text += s[j];
          j++;
        }
        cur();
        i = j + 1;
        continue;
      }
      if (c === '$' || c === '`') {
        cur().expands = true;
        if (c === '$' && s[i + 1] === '(') { const e = skipSubst(i + 2, ')'); cur().text += s.slice(i, e); i = e; continue; }
        if (c === '`') { const e = skipSubst(i + 1, '`'); cur().text += s.slice(i, e); i = e; continue; }
        cur().text += c;
        i++;
        continue;
      }
      if ('*?[{'.includes(c)) cur().expands = true;
      cur().text += c;
      i++;
    }
    endCmd();
    return { cmds, subs };
  };
  // wrappers looked through, and the pattern of their options that take a value
  const WRAP = {
    sudo: /^-[ugpCDhrtTUR]$/, doas: /^-[uC]$/, env: /^-[uSC]$/, timeout: /^-[sk]$/, nice: /^-n$/, ionice: /^-[cnpP]$/, stdbuf: /^-[ioe]$/,
    taskset: null, flock: /^-[wEs]$/, prlimit: /^-p$/, setsid: null, nohup: null, command: null, builtin: null, exec: /^-a$/, time: null,
    '!': null, then: null, do: null, else: null, elif: null, if: null, while: null, until: null, '{': null, '}': null,
  };
  const ASSIGN = /^[A-Za-z_][A-Za-z0-9_]*=/;
  const risky = (command, depth = 0) => {
    if (depth > 3) return null;
    const { cmds, subs } = lex(command);
    for (const sub of subs) { const hit = risky(sub, depth + 1); if (hit) return hit; }
    for (const words of cmds) {
      let i = 0;
      for (;;) {
        const t = words[i]?.text;
        if (t === undefined) break;
        if (ASSIGN.test(t)) { i++; continue; }
        if (!Object.hasOwn(WRAP, t)) break;
        const takes = WRAP[t];
        i++;
        while (words[i] && /^-/.test(words[i].text) && words[i].text !== '--') { if (takes?.test(words[i].text)) i++; i++; }
        if (words[i]?.text === '--') i++;
        if (t === 'env') while (words[i] && ASSIGN.test(words[i].text)) i++;
        if (t === 'timeout' && words[i] && /^[\d.]+[smhd]?$/.test(words[i].text)) i++;
        if (t === 'taskset' && words[i]) i++; // its mask or cpu list
        if (t === 'flock' && words[i]) i++; // its lock file or fd
      }
      const cmd = words[i]?.text ?? '';
      const rest = words.slice(i + 1);
      if (/^(?:\S*\/)?(?:ba|z|da)?sh$/.test(cmd)) {
        const k = rest.findIndex((x) => /^-\w*c\w*$/.test(x.text));
        if (k >= 0 && rest[k + 1]) { const hit = risky(rest[k + 1].text, depth + 1); if (hit) return hit; }
        continue;
      }
      if (cmd === 'eval') { const hit = risky(rest.map((x) => x.text).join(' '), depth + 1); if (hit) return hit; continue; }
      if (!/^(?:\S*\/)?(?:rm|rmdir)$/.test(cmd)) continue;
      let opts = true;
      for (const a of rest) {
        if (opts && a.text === '--') { opts = false; continue; }
        if (opts && /^-/.test(a.text) && !a.expands) continue;
        if (a.expands) return words.map((x) => x.text).join(' ');
      }
    }
    return null;
  };
  // the hook's input, read to its end (a slow writer's stdin may come in parts); never waits long
  const text = await new Promise((resolve) => {
    let d = '';
    const done = () => resolve(d);
    const timer = setTimeout(done, 5000);
    process.stdin.setEncoding('utf8');
    process.stdin.on('data', (c) => { d += c; });
    process.stdin.on('end', () => { clearTimeout(timer); done(); });
    process.stdin.on('error', () => { clearTimeout(timer); done(); });
  });
  let input = null;
  try { input = JSON.parse(text || 'null'); } catch {}
  let hit = null;
  try { hit = input?.tool_name && input.tool_name !== 'Bash' ? null : risky(input?.tool_input?.command); } catch { hit = null; }
  if (hit) process.stdout.write(`${JSON.stringify({ hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: `devteam: refused before it could stop on a permission prompt nobody answers: \`${hit.slice(0, 160)}\` removes a path built from a variable, glob or $(…). ${WHY}` } })}\n`);
  process.exit(0);
}

// A worktree's branch carries the kit as it was when the branch forked, but every session writes the
// one live log and answers to the rules on main, so in a project the main checkout's copy runs: a
// worker on an old branch otherwise gets old commands (an "unknown command" for one the docs name)
// and folds the log by old rules. Only where the main checkout holds a project (not the kit's own
// repo, whose worktrees are where the kit is changed); DEVTEAM_OWN_KIT=1 runs this copy anyway.
{
  const self = fileURLToPath(import.meta.url);
  let common = null;
  let top = null;
  // asked of the script's own folder, never of the caller's repo: git sets GIT_DIR for a hook and for
  // rebase --exec, and with it would take the script's folder for a checkout's top level
  const scriptGit = Object.fromEntries(Object.entries(process.env).filter(([k]) => !['GIT_DIR', 'GIT_WORK_TREE', 'GIT_COMMON_DIR', 'GIT_INDEX_FILE'].includes(k)));
  try { [common, top] = execFileSync('git', ['rev-parse', '--path-format=absolute', '--git-common-dir', '--show-toplevel'], { cwd: path.dirname(self), env: scriptGit, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim().split('\n'); } catch {}
  // A kit copied into a folder inside another checkout with no repo of its own (a fixture made
  // without git init) would take that checkout's git, and so its kit, home and live log: a kit in a
  // repo runs only as that checkout's own docs/devteam. (A kit in no repo, as a box image's, is free.)
  const cmd = process.argv[2];
  const real = (p) => { try { return fs.realpathSync(p); } catch { return p; } };
  if (top && cmd && !['help', '--help'].includes(cmd) && real(path.join(top, 'docs', 'devteam', 'scripts')) !== real(path.dirname(self))) {
    process.stderr.write(`devteam: this kit (${self}) is not its checkout's own (${path.join(top, 'docs', 'devteam')}): a copy inside another repo can't run against that repo's home; give the copy a repo of its own (git init)\n`);
    process.exit(1);
  }
  const kitMain = common && path.join(path.dirname(common), 'docs', 'devteam');
  const mainScript = kitMain && path.join(kitMain, 'scripts', 'devteam.mjs');
  if (mainScript && !process.env.DEVTEAM_OWN_KIT && path.resolve(mainScript) !== path.resolve(self) && fs.existsSync(path.join(kitMain, 'project')) && fs.existsSync(mainScript) && fs.readFileSync(mainScript, 'utf8') !== fs.readFileSync(self, 'utf8')) {
    const r = spawnSync(process.execPath, [mainScript, ...process.argv.slice(2)], { stdio: 'inherit' });
    process.exit(r.status ?? 1);
  }
}

// Object.groupBy is Node 21+.
const groupBy = (xs, key) => { const o = {}; for (const x of xs) (o[key(x)] ??= []).push(x); return o; };

process.stdout.on('error', (e) => {
  if (e.code === 'EPIPE') process.exit(0);
  throw e;
});

const argv = process.argv.slice(2);
const command = argv.shift();

/* args start */
// Flags take every following non-flag token as their value(s); put positionals before flags.
// --key=value takes the value whole, so a value that starts with -- can be passed.
// Everything after a bare `--` is left for commands that run another command (gate, act, link set).
function parseArgs(args) {
  const flags = {};
  const positional = [];
  const dash = args.indexOf('--');
  const own = dash === -1 ? args : args.slice(0, dash);
  for (let i = 0; i < own.length; i++) {
    const a = own[i];
    if (a.startsWith('--')) {
      const eq = a.indexOf('=');
      const key = eq > 2 ? a.slice(2, eq) : a.slice(2);
      const values = eq > 2 ? [a.slice(eq + 1)] : [];
      while (i + 1 < own.length && !own[i + 1].startsWith('--')) values.push(own[++i]);
      flags[key] = values.length === 0 ? true : values.length === 1 ? values[0] : values;
    } else positional.push(a);
  }
  return { flags, positional, rest: dash === -1 ? null : args.slice(dash + 1) };
}
/* args end */

const { flags, positional, rest } = parseArgs(argv);
const asList = (v) => (v === undefined || v === true ? [] : Array.isArray(v) ? v : [v]);
// A list flag: separate values, or one JSON array of strings. A single value that starts with "["
// but is not one is refused rather than stored as one item.
const listFlag = (k) => {
  const v = flags[k];
  if (typeof v !== 'string' || !v.trim().startsWith('[')) return asList(v);
  let parsed;
  try { parsed = JSON.parse(v); } catch { parsed = null; }
  if (!Array.isArray(parsed) || !parsed.every((x) => typeof x === 'string')) die(`--${k}: "${v}" looks like JSON but is not an array of strings; pass a JSON array of strings ('["a","b"]') or separate values ("a" "b")`);
  return parsed;
};
const flagStr = (k) => (flags[k] === undefined || flags[k] === true ? undefined : Array.isArray(flags[k]) ? flags[k].join(' ') : String(flags[k]));
const flagNum = (k) => (flagStr(k) === undefined ? undefined : Number(flagStr(k)));

function die(msg, code = 1) {
  process.stderr.write(`devteam: ${msg}\n`);
  // a line already logged is still announced: a partly posted set of secrets dies after its nudge
  deliverNudges();
  process.exit(code);
}
const warn = (msg) => process.stderr.write(`devteam: warning: ${msg}\n`);
const out = (s) => process.stdout.write(`${s}\n`);
// An owner action the dashboard runs replies on a pipe of its own (DEVTEAM_REPLY_FD) as soon as
// the command is done, with what it printed, and only then types into the supervisor's pane: a
// slow tmux never holds the owner's press. Read once and taken out of the environment, so nothing
// this process starts (a secret's sink) can write to the pipe.
const REPLY_FD = (() => { const v = process.env.DEVTEAM_REPLY_FD; delete process.env.DEVTEAM_REPLY_FD; return /^[3-9]$/.test(v ?? '') ? Number(v) : null; })();
let printed = '';
if (REPLY_FD !== null) { const write = process.stdout.write.bind(process.stdout); process.stdout.write = (c, ...rest) => { printed += String(c); return write(c, ...rest); }; }
const queuedNudges = [];
function replyNow() {
  if (REPLY_FD === null) return;
  try { fs.writeSync(REPLY_FD, `${JSON.stringify({ out: printed })}\n`); fs.closeSync(REPLY_FD); } catch {}
}
const json = (x) => out(JSON.stringify(x, null, 2));
const nowIso = () => new Date().toISOString();
const dateOnly = (iso) => iso.slice(0, 10);
const DAY = 864e5;

/* git reads start */
// A read-only command (dashboard-data, timeline) caches identical git reads for the rest of the
// process: one refresh asked git the same questions hundreds of times. Commands that write never
// turn this on, so they always read live.
let gitReadCache = null;
// Where a git call with no cwd runs: home's main checkout when this command runs outside home (a
// worker in another repo's worktree), else undefined, the cwd, as always (set in section 2).
let HOME_CWD;
const GIT_READS = new Set(['rev-parse', 'show', 'ls-tree', 'tag', 'merge-base', 'cat-file', 'log', 'for-each-ref', 'symbolic-ref', 'diff', 'rev-list', 'status']);
function git(args, cwd = HOME_CWD) {
  const key = gitReadCache && GIT_READS.has(args[0]) ? `${cwd ?? ''}\0${args.join('\0')}` : null;
  if (key && gitReadCache.has(key)) return gitReadCache.get(key);
  let r;
  try {
    r = execFileSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'], maxBuffer: 64 * 1024 * 1024 }).replace(/\n$/, '');
  } catch {
    r = null;
  }
  if (key) gitReadCache.set(key, r);
  return r;
}
function gitOrDie(args, cwd = HOME_CWD) {
  try {
    return execFileSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
  } catch (e) {
    die(`git ${args.join(' ')} failed: ${(e.stderr || e.message).toString().trim()}`);
  }
}
// This checkout's own HEAD, branch and working tree, wherever it is: a worker in another repo's
// worktree records its own head, while every other read goes to home (HOME_CWD).
const cwdGit = (args) => git(args, process.cwd());
const cwdGitOrDie = (args) => gitOrDie(args, process.cwd());
// git's exit status and its bytes: the one runner that tells "no" (an ancestor check's 1) from an
// error (128, an object not here yet), which git() folds into one null.
function gitStatus(args, cwd = HOME_CWD) {
  const r = spawnSync('git', args, { cwd, stdio: ['ignore', 'pipe', 'ignore'], maxBuffer: 64 * 1024 * 1024 });
  return { status: r.error ? null : r.status, stdout: r.stdout ?? Buffer.alloc(0) };
}
// What `git cat-file --batch` printed, as a Map of each spec to { type, oid, bytes }, or null for a
// spec git called missing or ambiguous. Sizes are in bytes, so the output is read as bytes; output
// cut short leaves the rest null, never a slice of the next object.
function parseBatch(buf, specs) {
  const res = new Map(specs.map((s) => [s, null]));
  let at = 0;
  for (const spec of specs) {
    const nl = buf.indexOf(10, at);
    if (nl === -1) break;
    const head = buf.toString('latin1', at, nl).split(' ');
    at = nl + 1;
    if (head.length !== 3 || !/^[0-9a-f]{40}([0-9a-f]{24})?$/.test(head[0])) continue; // "<spec> missing"
    const size = Number(head[2]);
    if (!Number.isSafeInteger(size) || at + size + 1 > buf.length) break;
    res.set(spec, { oid: head[0], type: head[1], bytes: buf.subarray(at, at + size) });
    at += size + 1;
  }
  return res;
}
// Many objects in one git call (each spec <sha>:<path> or an oid). A spec with a newline is never
// sent (it would be two specs). A failed call returns null: the caller asks one at a time.
function gitBatch(specs, cwd = HOME_CWD) {
  const ok = specs.filter((s) => !/[\n\r]/.test(s));
  let buf = Buffer.alloc(0);
  if (ok.length) {
    try { buf = execFileSync('git', ['cat-file', '--batch'], { cwd, input: `${ok.join('\n')}\n`, stdio: ['pipe', 'pipe', 'ignore'], maxBuffer: 256 * 1024 * 1024 }); } catch { return null; }
  }
  const got = parseBatch(buf, ok);
  return new Map(specs.map((s) => [s, got.get(s) ?? null]));
}
// Reads at a commit, kept for the whole process in every command: a sha names the same bytes
// forever, so even a command that writes can't read them stale. Keyed by the repository (its
// common git dir, so its worktrees share), the sha and the path. Text comes back as git() gives it:
// one trailing newline taken off.
const FULL_SHA = /^[0-9a-f]{40}([0-9a-f]{24})?$/;
const commonDirs = new Map();
function gitCommonDirOf(cwd = HOME_CWD) {
  const k = cwd ?? process.cwd();
  if (!commonDirs.has(k)) commonDirs.set(k, git(['rev-parse', '--path-format=absolute', '--git-common-dir'], cwd) ?? k);
  return commonDirs.get(k);
}
const atCommit = new Map();
const atKey = (sha, p, cwd) => `${gitCommonDirOf(cwd)}\0${sha}\0${p}`;
const asGitText = (o) => (o ? o.bytes.toString('utf8').replace(/\n$/, '') : null);
function prefetchAt(sha, paths, cwd = HOME_CWD) {
  if (!FULL_SHA.test(sha ?? '')) return;
  const need = [...new Set(paths)].filter((p) => !/[\n\r]/.test(p) && !atCommit.has(atKey(sha, p, cwd)));
  if (!need.length) return;
  const got = gitBatch(need.map((p) => `${sha}:${p}`), cwd);
  if (!got) return;
  for (const p of need) { const o = got.get(`${sha}:${p}`); atCommit.set(atKey(sha, p, cwd), o && o.type === 'blob' ? o : null); }
}
