  for (let i = 0; i < m[2].length;) { if (m[2][i] === '%') { bytes.push(parseInt(m[2].slice(i + 1, i + 3), 16)); i += 3; } else { bytes.push(m[2].charCodeAt(i)); i += 1; } }
