const droppedWords = (files) => (files?.length ? ` (${plural(files.length, 'file')} dropped)` : '');
const droppedPaths = (files) => (files?.length ? files.map((f) => f.path) : null);
const myAddress = () => { const w = logWriter(); return w === 'supervisor' ? 'supervisor' : w; };

